css:
#tongsci1-3-3-3-diffuse .df-body { grid-template-columns: 1120px minmax(0, 1fr); }
#tongsci1-3-3-3-diffuse .df-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #f5f2ea; }
#tongsci1-3-3-3-diffuse .df-stage canvas { touch-action: none; cursor: grab; user-select: none; -webkit-user-select: none; }
#tongsci1-3-3-3-diffuse .df-stage .now-chip { top: auto; bottom: 52px; left: 24px; }
#tongsci1-3-3-3-diffuse .df-panel { gap: 12px; }
#tongsci1-3-3-3-diffuse .df-out { margin: 0; font-size: 20px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 10px 14px; min-height: 6.2em; flex: none; }
#tongsci1-3-3-3-diffuse .df-out b { color: var(--accent); }
#tongsci1-3-3-3-diffuse .df-tab { width: 100%; border-collapse: collapse; table-layout: fixed; font: 600 16px/1.3 var(--f-body); flex: none; background: var(--paper-2); border: 2px solid var(--ink); }
#tongsci1-3-3-3-diffuse .df-tab thead th { font: 800 17px/1.2 var(--f-body); background: color-mix(in srgb, #2a6f97 12%, var(--paper-2)); border: 1.5px solid var(--ink-3); padding: 5px 4px; color: #1f4f6e; }
#tongsci1-3-3-3-diffuse .df-tab thead th.fa { color: #9a4d10; background: color-mix(in srgb, #e8893a 14%, var(--paper-2)); }
#tongsci1-3-3-3-diffuse .df-tab thead small, #tongsci1-3-3-3-diffuse .df-tab td small { font-size: 14px; color: var(--ink-3); font-weight: 600; }
#tongsci1-3-3-3-diffuse .df-tab tbody th { font: 700 15px/1.2 var(--f-body); border: 1.5px solid var(--rule, #c9ccd3); background: color-mix(in srgb, var(--ink) 4%, var(--paper-2)); padding: 4px; }
#tongsci1-3-3-3-diffuse .df-tab td { border: 1.5px solid var(--rule, #c9ccd3); padding: 5px 7px; vertical-align: middle; }
#tongsci1-3-3-3-diffuse .df-def { margin: 0; display: grid; gap: 8px; flex: none; }
#tongsci1-3-3-3-diffuse .df-def div { border-left: 6px solid #2a6f97; background: color-mix(in srgb, #2a6f97 9%, var(--paper-2)); border-radius: 0 10px 10px 0; padding: 6px 14px; }
#tongsci1-3-3-3-diffuse .df-def dt { font: 800 19px var(--f-body); color: #1f4f6e; }
#tongsci1-3-3-3-diffuse .df-def dd { margin: 2px 0 0; font-size: 18px; line-height: 1.45; }
section#tongsci1-3-3-3-diffuse.ex.u-done .df-def { display: none; }

